mapper.select:
SELECT sd.id, sd.parent_id, sd.dept_code, sd.dept_name, sd.sort_order, sd.status, sd.created_at, su.real_name AS leader_name FROM sys_department sd LEFT JOIN sys_user su ON sd.leader_id = su.id AND su.deleted = 0 WHERE sd.deleted = 0
AND sd.parent_id = #{query.parentId}
AND sd.status = #{query.status}
AND ( sd.dept_code LIKE CONCAT('%', #{query.keyword}, '%') OR sd.dept_name LIKE CONCAT('%', #{query.keyword}, '%') )
ORDER BY sd.sort_order ASC, sd.created_at DESC
